cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void batchnorm2d_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps, float momentum)
{
    int c = blockIdx.x;
    int HW = H * W;
    int64_t count = (int64_t)N * (int64_t)HW;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const T* Xc = X + (int64_t)c * (int64_t)HW;
    T* Yc = Y + (int64_t)c * (int64_t)HW;
    int HW4 = HW / 4;
    int rem = HW - HW4 * 4;
    int64_t count4 = (int64_t)N * (int64_t)HW4;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float sum = 0.f, sumsq = 0.f;
    // Vectorized reduction over contiguous float4 groups along HW
    for (int64_t idx = tid; idx < count4; idx += nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* ptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4 v4 = *ptr;
        sum   += v4.x + v4.y + v4.z + v4.w;
        sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    // Tail elements (when HW is not divisible by 4)
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = tid; idx < tailCount; idx += nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            sum   += v;
            sumsq += v * v;
        }
    }
    // Warp-level reduction using shuffle instructions to reduce synchronization overhead
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    extern __shared__ float sdata[];
    int warpId = tid / warpSize;
    int laneId = tid % warpSize;
    int numWarps = (nthreads + warpSize - 1) / warpSize;
    float* ssum   = sdata;
    float* ssumsq = sdata + numWarps;
    if (laneId == 0) {
        ssum[warpId]   = sum;
        ssumsq[warpId] = sumsq;
    }
    __syncthreads();
    __shared__ float mean_s, invstd_s;
    if (tid == 0) {
        float total_sum = 0.f, total_sumsq = 0.f;
        for (int i = 0; i < numWarps; ++i) {
            total_sum   += ssum[i];
            total_sumsq += ssumsq[i];
        }
        float m   = total_sum / (float)count;
        float var = total_sumsq / (float)count - m * m; // biased variance
        if (var < 0.f) var = 0.f;
        mean_s   = m;
        invstd_s = rsqrtf(var + eps);
        float unbiased_var = (count > 1) ? (var * (float)count / (float)(count - 1)) : var;
        running_mean[c] = (T)((1.0f - momentum) * (float)running_mean[c] + momentum * m);
        running_var[c]  = (T)((1.0f - momentum) * (float)running_var[c]  + momentum * unbiased_var);
    }
    __syncthreads();
    float mean   = mean_s;
    float invstd = invstd_s;
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;
    // Vectorized normalize + write-back
    for (int64_t idx = tid; idx < count4; idx += nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* xptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4* yptr = reinterpret_cast<float4*>(Yc + n * channel_stride + hw4 * 4);
        float4 v4 = *xptr;
        float4 y4;
        y4.x = (v4.x - mean) * invstd * w + b;
        y4.y = (v4.y - mean) * invstd * w + b;
        y4.z = (v4.z - mean) * invstd * w + b;
        y4.w = (v4.w - mean) * invstd * w + b;
        *yptr = y4;
    }
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = tid; idx < tailCount; idx += nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            float y = (v - mean) * invstd * w + b;
            Yc[n * channel_stride + hw] = static_cast<T>(y);
        }
    }
}
