    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    const T* __restrict__ running_mean,
    const T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps)
{
    int c = blockIdx.x;
    int HW = H * W;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const T* Xc = X + (int64_t)c * (int64_t)HW;
    T* Yc = Y + (int64_t)c * (int64_t)HW;
    int HW4 = HW / 4;
    int rem = HW - HW4 * 4;
    int64_t count4 = (int64_t)N * (int64_t)HW4;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float mean = static_cast<float>(running_mean[c]);
    float var  = static_cast<float>(running_var[c]);
    float invstd = rsqrtf(var + eps);
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;
    for (int64_t idx = tid; idx < count4; idx += nthreads) {
        int64_t n   = idx / HW4;
        int64_t hw4 = idx - n * HW4;
        const float4* xptr = reinterpret_cast<const float4*>(Xc + n * channel_stride + hw4 * 4);
        float4* yptr = reinterpret_cast<float4*>(Yc + n * channel_stride + hw4 * 4);
        float4 v4 = *xptr;
        float4 y4;
        y4.x = (v4.x - mean) * invstd * w + b;
        y4.y = (v4.y - mean) * invstd * w + b;
        y4.z = (v4.z - mean) * invstd * w + b;
        y4.w = (v4.w - mean) * invstd * w + b;
        *yptr = y4;
    }
    if (rem > 0) {
        int64_t tailCount = (int64_t)N * rem;
        for (int64_t idx = tid; idx < tailCount; idx += nthreads) {
            int64_t n  = idx / rem;
            int64_t r  = idx - n * rem;
            int64_t hw = (int64_t)HW4 * 4 + r;
            float v = static_cast<float>(Xc[n * channel_stride + hw]);
            float y = (v - mean) * invstd * w + b;
            Yc[n * channel_stride + hw] = static_cast<T>(y);
        }
    }
}
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   double eps,
                                   double momentum,
                                   bool training) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();
    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);
    TORCH_CHECK(w_c.size(0) == C, "weight size mismatch");
    TORCH_CHECK(b_c.size(0) == C, "bias size mismatch");
    TORCH_CHECK(rm_c.size(0) == C, "running_mean size mismatch");
    TORCH_CHECK(rv_c.size(0) == C, "running_var size mismatch");
    auto y = torch::empty_like(x_c);
    const int threads = 512;
    dim3 block(threads);
    dim3 grid(C);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (training) {
        size_t shmem = 2 * ((threads + 31) / 32) * sizeof(float);
        batchnorm2d_kernel<float><<<grid, block, shmem, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            N, C, H, W,
            (float)eps, (float)momentum
        );
    } else {
        batchnorm2d_eval_kernel<float><<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            N, C, H, W,
            (float)eps
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d_kernel launch failed: ", cudaGetErrorString(err));
    if (training) {
        // copy updated running stats back into the passed tensors (in case they were not the same storage)
        running_mean.copy_(rm_c);
        running_var.copy_(rv_c);
    }
    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a custom CUDA/CuTe kernel.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous().float()
        out = self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            float(self.eps),
            float(self.momentum),
            bool(self.training),
        )
        if self.training:
            self.num_batches_tracked += 1
        return out

