        out = self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            float(self.eps),
            float(self.momentum),
            bool(self.training),
        )
        if self.training:
            self.num_batches_tracked += 1
